import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.Cs5aHXsR.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"google-search-console-mcp","text":"Search Console, in the conversation","tagline":"MCP server for Google Search Console — create and verify properties, submit sitemaps, query search analytics and inspect URLs","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/google-search-console-mcp"}]},"features":[{"title":"Creates a property that actually works","details":"Getting one takes four steps in a fixed order and nothing in the API enforces it — add_site on an unverified domain succeeds and leaves a property that answers 403 for every piece of data. setup_site reports which step is missing and hands over the DNS record to paste."},{"title":"Three APIs, not one","details":"Search Console does not include ownership. Site Verification is a separate service with its own scope, its own host and an incompatible way of naming the same site; the Indexing API is a third. All three are covered, and the translation between them is handled for you."},{"title":"Only the tools you want","details":"GSC_READ_ONLY=true registers the twelve read tools and nothing else. GSC_ALLOW_TOOLS cuts finer — essential for a curated five, your own comma-separated list, or a whole family with list_* — and GSC_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing. Narrowing the list narrows the OAuth scopes it asks Google for."},{"title":"Irreversible calls ask a person","details":"delete_site, delete_sitemap, unverify_site and update_site_owners raise a real dialog through MCP elicitation — one the model cannot answer on its behalf. Where the client cannot show one they fall back to a single-use token bound to the exact arguments, and say which of the two it was rather than implying somebody approved."},{"title":"Numbers you can quote","details":"CTR comes from the totals rather than an average of row CTRs, average position is weighted by impressions, and the result says plainly that rows do not sum to the property total when the query dimension is used."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380633000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 300`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`How google-search-console-mcp connects an MCP client to three Google APIs`),t(`desc`,{id:`arch-desc`},`An MCP client talks to google-search-console-mcp over stdio. The server calls three separate Google services over HTTPS: the Search Console API for properties, sitemaps and analytics; the Site Verification API for proving ownership; and the Indexing API for change notifications. Each is requested with its own OAuth scope, and only when a registered tool needs it.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`16`,y:`110`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`91`,y:`143`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`91`,y:`163`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`248`,y:`100`,width:`196`,height:`100`,rx:`10`}),t(`text`,{class:`label-title`,x:`346`,y:`133`,"text-anchor":`middle`},`Search Console MCP`),t(`text`,{class:`label-muted`,x:`346`,y:`153`,"text-anchor":`middle`},`21 tools, 5 essential`),t(`text`,{class:`label-muted`,x:`346`,y:`173`,"text-anchor":`middle`},`asks a person`),t(`path`,{class:`edge-accent`,d:`M166,150 L240,150`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`203`,y:`138`,"text-anchor":`middle`},`stdio`),t(`rect`,{class:`node`,x:`530`,y:`26`,width:`176`,height:`66`,rx:`10`}),t(`text`,{class:`label-title`,x:`618`,y:`53`,"text-anchor":`middle`},`Search Console`),t(`text`,{class:`label-muted`,x:`618`,y:`72`,"text-anchor":`middle`},`sitemaps, analytics`),t(`rect`,{class:`node`,x:`530`,y:`117`,width:`176`,height:`66`,rx:`10`}),t(`text`,{class:`label-title`,x:`618`,y:`144`,"text-anchor":`middle`},`Site Verification`),t(`text`,{class:`label-muted`,x:`618`,y:`163`,"text-anchor":`middle`},`proves ownership`),t(`rect`,{class:`node`,x:`530`,y:`208`,width:`176`,height:`66`,rx:`10`}),t(`text`,{class:`label-title`,x:`618`,y:`235`,"text-anchor":`middle`},`Indexing`),t(`text`,{class:`label-muted`,x:`618`,y:`254`,"text-anchor":`middle`},`change notices`),t(`path`,{class:`edge-accent`,d:`M444,138 L522,66`,"marker-end":`url(#arch-arrow-accent)`}),t(`path`,{class:`edge-accent`,d:`M444,150 L522,150`,"marker-end":`url(#arch-arrow-accent)`}),t(`path`,{class:`edge-accent`,d:`M444,162 L522,234`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`487`,y:`108`,"text-anchor":`middle`},`HTTPS`),t(`text`,{class:`label-muted`,x:`487`,y:`196`,"text-anchor":`middle`},`one scope each`)]),t(`figcaption`,null,`The server talks to three separate Google services. Search Console alone cannot create a working property — ownership lives in the Site Verification API, on a different host, behind a different scope, naming the same site a different way.`)],-1),r(`<h2 id="_21-tools-or-five" tabindex="-1">21 tools, or five <a class="header-anchor" href="#_21-tools-or-five" aria-label="Permalink to “21 tools, or five”">​</a></h2><p>The tool list is not fixed. <code>GSC_ALLOW_TOOLS=essential</code> narrows it to the five that cover looking at a property — which properties exist, what their sitemaps did, what the Performance report says, and whether one URL is indexed — and a name that matches nothing stops the server instead of quietly leaving a tool out of <code>tools/list</code>.</p><p>Narrowing the list narrows the credential with it: the OAuth scopes this server requests are derived from the tools that are actually registered. A server denied the Indexing tools never asks Google for the Indexing scope, which is the difference between working and not for a service account under domain-wide delegation.</p><p>The server starts without any configuration at all, so registries and inspectors can introspect it; every call then fails with setup instructions instead of reaching Google.</p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start google-search-console-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,7)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};